  "Charming open-air riverside dining terrace along Sisowath Quay serving royal and traditional Khmer recipes.": "位于金边西索瓦河畔大道的迷人露天临江餐厅，迎着四臂湾清凉晚风，供应正宗高棉皇室佳肴与传统河鲜名菜。",
  "Iconic authentic Cambodian restaurant set in a charming wooden house in Siem Reap, globally celebrated for Fish Amok.": "坐落于暹粒传统高脚木屋内的标志性高棉餐厅，凭借遵循古法烹制的醇厚鱼阿莫克（Fish Amok）与家传食谱享誉全球。",
