  "Award-winning restaurant featured in Asia's 50 Best, blending traditional Khmer flavors with modern techniques.": "荣登“亚洲50佳餐厅”榜单的殿堂级名厨餐厅，严选本土野生香草与应季食材，将传统高棉风味与现代法式烹饪技艺完美交融。",
  "Lush garden training restaurant by TREE Alliance serving innovative tapas and traditional Khmer recipes.": "坐落于繁茂热带花园中的 TREE Alliance 公益培训餐厅，供应富有巧思的高棉创意料理、传统名菜与花园甜品。",
  "Beloved social-purpose dining destination helping disadvantaged youth, serving delicious Khmer curries and stir-fries.": "备受赞誉的暹粒社会公益餐厅，助力当地青年职业成长，在温馨庭院中供应醇香高棉咖喱、经典小炒与素食友好菜品。",
  "Chic 1960s-inspired modernist venue surrounded by lotus ponds serving elevated Khmer traditional dishes.": "被清幽荷花池环绕的1960年代复古现代主义风格餐厅，在极具格调的氛围中呈现精雕细琢的传统高棉名菜。",
  "Architecturally stunning bamboo pavilion training venue serving exquisite modern twists on Cambodian street classics.": "坐落于壮观生态竹构凉亭内的餐饮学院培训餐厅，将地道柬埔寨街头美食转化为精致考究的现代料理。",
  "Visionary young Cambodian chef Mengly crafts culinary magic utilizing wild herbs and ancestral techniques.": "由充满远见的柬埔寨青年名厨 Mengly 主理，巧妙运用山林野生香草与高棉古法炭烤技艺，演绎令人惊艳的新派高棉料理。",
